 prod=json.loads((root/manifests[1]).read_text(encoding='utf-8-sig')); cases=prod.get('cases',[]); return {'tracked':files,'pins':pins,'product_case_count':len(cases),'product_ids_unique':len({c.get('case_id') for c in cases})==len(cases)}
