cmd=[sys.executable,'-m','unittest','-v','review.test_pilot_runroot_manifest'];t=time.monotonic();p=subprocess.run(cmd,cwd=root,env={k:v for k,v in os.environ.items() if k!='PYTHONPATH'},stdout=subprocess.PIPE,stderr=subprocess.PIPE);dur=round(time.monotonic()-t,3)
(out/'stdout.txt').write_bytes(p.stdout);(out/'stderr.txt').write_bytes(p.stderr);(out/'exit').write_text(str(p.returncode)+'\n',encoding='ascii')
a=snap();(out/'hashes-after.json').write_text(json.dumps(a,indent=2)+'\n',encoding='utf-8'); stderr=p.stderr.decode('utf-8','replace')
summary={'classification':'PYTHON_MANIFEST_REGRESSION_ONLY_NOT_PILOTQUOTA_GO_OR_PLAYWRIGHT','command':cmd,'cwd':str(root),'python':sys.version,'exit_code':p.returncode,'elapsed_seconds':dur,'stdout_bytes':len(p.stdout),'stderr_bytes':len(p.stderr),'tracked_hashes_stable':b['tracked']==a['tracked'],'source_hash_pins_before':{'total':len(b['pins']),'passed':sum(x['match'] for x in b['pins']),'failures':[x for x in b['pins'] if not x['match']]},'source_hash_pins_after':{'total':len(a['pins']),'passed':sum(x['match'] for x in a['pins']),'failures':[x for x in a['pins'] if not x['match']]},'product_case_count':a['product_case_count'],'product_ids_unique':a['product_ids_unique'],'api26_test_passed':'test_api26_separates_permit_and_issued_failure_side_effects' in stderr and 'test_api26_separates_permit_and_issued_failure_side_effects' in stderr and '... ok' in stderr[stderr.find('test_api26_separates_permit_and_issued_failure_side_effects'):stderr.find('\n',stderr.find('test_api26_separates_permit_and_issued_failure_side_effects'))+1],'ui09_test_passed':'test_ui09_issued_uncertainty_never_leaks_or_retries_a_handle' in stderr and '... ok' in stderr[stderr.find('test_ui09_issued_uncertainty_never_leaks_or_retries_a_handle'):stderr.find('\n',stderr.find('test_ui09_issued_uncertainty_never_leaks_or_retries_a_handle'))+1],'candidate_execution_invoked':False}
(out/'summary.json').write_text(json.dumps(summary,indent=2)+'\n',encoding='utf-8');print(json.dumps({k:summary[k] for k in ('exit_code','elapsed_seconds','tracked_hashes_stable','source_hash_pins_before','source_hash_pins_after','product_case_count','product_ids_unique','api26_test_passed','ui09_test_passed','candidate_execution_invoked')},indent=2))
